-- The Cheese Course HQ: team settings an admin edits on the Team page.
-- Generated by scripts/gen-migration.ts. Run after 0002_operations.sql.

alter table public.profiles add column if not exists title text not null default '';
alter table public.profiles add column if not exists status text not null default 'active' check (status in ('active', 'paused'));
alter table public.profiles add column if not exists workspaces text[];
alter table public.profiles add column if not exists access text[];

-- Paused people get no role, so every policy shuts them out until they're switched back on.
create or replace function public.my_role() returns text
language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid() and status = 'active'
$$;

-- The pages an admin switched on for this person ("miami:/finance"), or none.
create or replace function public.my_access() returns text[]
language sql stable security definer set search_path = public as $$
  select coalesce(access, '{}') from public.profiles where id = auth.uid() and status = 'active'
$$;

-- Only admins change the new columns (the existing admin policy on profiles already covers updates).

drop policy if exists "granted read stores" on public.stores;
create policy "granted read stores" on public.stores for select using (
  public.my_access() && array['miami:/ops/stores', 'miami:/ops/staff', 'spain:/ops/stores', 'spain:/ops/staff']
  and (public.my_role() <> 'store_manager' or name is null or name = 'Both stores' or name = public.my_store())
);

drop policy if exists "granted read staff" on public.staff;
create policy "granted read staff" on public.staff for select using (
